import { FALLBACK_MENU_IMAGE, menuImageMap as intendedMenuImageMap, getMenuImageAlt as intendedAlt } from "./menu-images";

/** Dedicated photograph when it exists; closest honest existing photo otherwise. */
export function getMenuImage(dishName: string): string {
  return availableMenuImageMap[dishName] ?? FALLBACK_MENU_IMAGE;
}

/** Alt text describes the photograph actually displayed. */
export function getMenuImageAlt(dishName: string): string {
  const src = availableMenuImageMap[dishName];
  if (src && src === intendedMenuImageMap[dishName]) return intendedAlt(dishName);
  return `${dishName} from the FULL MOONs Family Restaurant menu`;
}

/** Representative category thumbnail, safe against missing files. */
export function getCategoryImage(category: string): string {
  return availableCategoryImageMap[category] ?? FALLBACK_MENU_IMAGE;
}
